class Solution {
public:
    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> vals;
        for (ListNode* curr = head; curr; curr = curr->next) {
            vals.push_back(curr->val);
        }
        int n = vals.size();
        vector<int> res(n, 0);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && vals[st.back()] < vals[i]) {
                res[st.back()] = vals[i];
                st.pop_back();
            }
            st.push_back(i);
        }
        return res;
    }
};

class Solution {
    public int[] nextLargerNodes(ListNode head) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode curr = head; curr != null; curr = curr.next) {
            vals.add(curr.val);
        }
        int n = vals.size();
        int[] res = new int[n];
        int[] st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            int v = vals.get(i);
            while (top > 0 && vals.get(st[top - 1]) < v) {
                res[st[--top]] = v;
            }
            st[top++] = i;
        }
        return res;
    }
}

var nextLargerNodes = function(head) {
    const vals = [];
    let curr = head;
    while (curr) {
        vals.push(curr.val);
        curr = curr.next;
    }
    const res = new Array(vals.length).fill(0);
    const st = [];
    for (let i = 0; i < vals.length; i++) {
        const v = vals[i];
        while (st.length > 0 && vals[st[st.length - 1]] < v) {
            res[st.pop()] = v;
        }
        st.push(i);
    }
    return res;
};
